python3 - <<'PY'
import json
p='/workspace/contracts/openapi.contract.json'; d=json.load(open(p))
print('paths',len(d['paths']))
for path, methods in d['paths'].items():
 for method, op in methods.items():
  if method.startswith('x-'): continue
  req=[]
  for p in op.get('parameters',[]): req.append(f"param:{p['name']}({p.get('in')})")
  rb=op.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema',{})
  if rb: req.append('body:'+','.join(rb.get('required',[])))
  print(method.upper(),path,op.get('operationId'),'REQ', ';'.join(req),'RESP',','.join(op.get('responses',{})))
print('\ncomponents', list(d.get('components',{})))
for n,s in d.get('components',{}).get('schemas',{}).items(): print(n, s.get('type'), s.get('required'))
PY

