python3 - <<'PY'
import json,pprint
D=json.load(open('/workspace/contracts/openapi.contract.json'))
for path,ms in D['paths'].items():
 for m,o in ms.items():
  if m.startswith('x-'): continue
  print('\n###',m.upper(),path,o['operationId'])
  rb=o.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema')
  if rb: print('REQUEST',json.dumps(rb,indent=2))
  for code,r in o['responses'].items():
   if code in ('200','201','101'):
    s=r.get('content',{}).get('application/json',{}).get('schema')
    if s: print('RESPONSE',code,json.dumps(s,indent=2))
PY

