mkdir -p /workspace/backend /workspace/frontend/src /workspace/app-setup /workspace/data && cp /workspace/contracts/openapi.contract.json /workspace/app-setup/openapi.json && cat > /workspace/backend/go.mod <<'EOF'
module lablogistics

go 1.22
EOF
cat > /workspace/backend/main.go <<'EOF'
package main

import (
 "crypto/sha256"
 "encoding/hex"
 "encoding/json"
 "fmt"
 "log"
 "net/http"
 "os"
 "path/filepath"
 "strings"
 "sync"
 "time"
)

type User struct { ID, Username, FullName, Password string; Roles []string; ActiveRole string; Active bool; Qualifications []string; AssignedLocationID string }
type SampleType struct { ID, Name, ContainerType string; TemperatureMinC, TemperatureMaxC float64; QualifiedCollectorRequired bool; RequiredQualification string; IncompatibleSampleTypes []string; RequiresCooledRoute, BatchingAllowed bool }
type Location struct { ID, Name string; Latitude, Longitude float64; Active bool; Functions map[string]bool; CoverageKm float64; HandlingMinutes int }
type Sample struct { ID, RequestID, RequesterID, JourneyID, SampleTypeID, State, OriginType, OriginNodeID, CurrentHolderID string; Origin map[string]float64; RequestedAt, DeliveryDeadline, EarliestCollectionAt, LatestCollectionAt string; ContainerType string; TemperatureMinC, TemperatureMaxC float64; Sealed bool; LocationStale bool; Timeline []map[string]interface{}; AssignmentIDs []string; TargetLaboratoryID string }
type Assignment struct { ID, SampleID, WorkerID, Status, Kind string; Offered bool }
type Journey struct { ID string; SampleIDs []string; PlanVersion int; Status, RouteMode string; AssignmentIDs []string }
type Audit struct { ID, ActorID, Role, Action, EntityType, EntityID string; Success bool; OccurredAt string; Details map[string]interface{} }
type State struct { Users map[string]User; SampleTypes map[string]SampleType; Locations map[string]Location; Samples map[string]Sample; Assignments map[string]Assignment; Journeys map[string]Journey; Sessions map[string]string; Audits []Audit; Version int }
var mu sync.Mutex
var state State
var stateFile = "/workspace/data/state.json"

func uuid() string { b:=make([]byte,16); for i:=range b { b[i]=byte(time.Now().UnixNano()>>uint((i%8)*8)) ^ byte(i*31) }; return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x", b[:4], b[4:6], b[6:8], b[8:10], b[10:]) }
